#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEngine;
using UnityEngine.UI;
public sealed class ChamberShipMaskCapture:MonoBehaviour
{
    string output;int checks;
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Boot(){if(!Environment.GetCommandLineArgs().Contains("-chamber-ship-capture"))return;Application.runInBackground=true;var dir=Path.GetFullPath(Path.Combine(Application.dataPath,"../Captures/ChamberShip"));Directory.CreateDirectory(dir);SaveGames.TestRoot=Path.Combine(dir,"Saves");Directory.CreateDirectory(SaveGames.TestRoot);VariableSingleton.TestSavePath=Path.Combine(SaveGames.TestRoot,"checkpoint.besieged.json");var go=new GameObject("Window ship verification");DontDestroyOnLoad(go);go.AddComponent<ChamberShipMaskCapture>().output=dir;}
    void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;}
    IEnumerator Start(){var work=new Stack<IEnumerator>();work.Push(Run());while(work.Count>0){object next=null;bool more=false;try{more=work.Peek().MoveNext();if(more)next=work.Peek().Current;}catch(Exception ex){File.WriteAllText(Path.Combine(output,"checks.txt"),"FAILED "+checks+"\n"+ex);Application.Quit(1);yield break;}if(!more){work.Pop();continue;}if(next is IEnumerator inner)work.Push(inner);else yield return next;}File.WriteAllText(Path.Combine(output,"checks.txt"),checks+" checks passed");Application.Quit(0);}
    static float Cross(Vector2 a,Vector2 b,Vector2 p)=>(b.x-a.x)*(p.y-a.y)-(b.y-a.y)*(p.x-a.x);
    static bool Covered(Mesh mesh,Rect r,Vector2 uv){Vector2 p=new Vector2(r.xMin+uv.x*r.width,r.yMin+uv.y*r.height);var v=mesh.vertices;var t=mesh.triangles;for(int i=0;i<t.Length;i+=3){float a=Cross(v[t[i]],v[t[i+1]],p),b=Cross(v[t[i+1]],v[t[i+2]],p),c=Cross(v[t[i+2]],v[t[i]],p);if((a>=-.0001f&&b>=-.0001f&&c>=-.0001f)||(a<=.0001f&&b<=.0001f&&c<=.0001f))return true;}return false;}
    IEnumerator Run(){AudioListener.volume=0;yield return null;SaveMenu.StartCampaign(false);float until=Time.realtimeSinceStartup+30;while(!VariableSingleton.IsInitialized&&Time.realtimeSinceStartup<until)yield return null;Check(VariableSingleton.IsInitialized,"campaign initialized");yield return new WaitForSecondsRealtime(.5f);CampaignHUD.Instance.DismissReport();var manager=FindObjectOfType<ManagerUI>(true);manager.gameObject.SetActive(true);var chamber=manager.GetComponentInChildren<CouncilChamber>();Check(chamber!=null,"live chamber found");chamber.ForceStill=true;
        string state=JsonUtility.ToJson(VariableSingleton.Instance.CaptureState()),rng=JsonUtility.ToJson(UnityEngine.Random.state);var mask=chamber.GetComponentInChildren<ChamberWindowMask>();var ship=chamber.GetComponentsInChildren<RawImage>().Single(i=>i.name=="Passing merchantman");var elapsed=typeof(CouncilChamber).GetField("<Elapsed>k__BackingField",BindingFlags.Instance|BindingFlags.NonPublic);
        foreach(int width in new[]{1280,1600}){Screen.SetResolution(width,width==1280?720:900,false);yield return new WaitForSecondsRealtime(1.5f);Canvas.ForceUpdateCanvases();var mesh=new Mesh();using(var helper=new VertexHelper()){typeof(ChamberWindowMask).GetMethod("OnPopulateMesh",BindingFlags.Instance|BindingFlags.NonPublic,null,new[]{typeof(VertexHelper)},null).Invoke(mask,new object[]{helper});helper.FillMesh(mesh);}Check(mesh.triangles.Length==180,"both complete thirty-triangle fans");
            foreach(float x in new[]{.77f,.81f,.86f,.90f,.94f,.965f})foreach(float y in new[]{.60f,.62f,.66f})Check(Covered(mesh,mask.rectTransform.rect,new Vector2(x,y)),"lower window has no diagonal clipping hole "+x+" "+y);
            Check(!Covered(mesh,mask.rectTransform.rect,new Vector2(.735f,.65f))&&!Covered(mesh,mask.rectTransform.rect,new Vector2(.985f,.65f)),"window jambs still occlude");
            foreach(float time in new[]{0f,14f,22f,26.4f,30.8f,34f,38f,43.99f,44.01f,63.99f,64.01f}){elapsed.SetValue(chamber,time);chamber.SendMessage("Render");bool sailing=Mathf.Repeat(time,64)<44;Check(ship.enabled==sailing,"no mid-journey renderer switch "+time);if(time>=14&&time<=30.8f){var point=CouncilChamber.ShipPoint(time/44);Check(Covered(mesh,mask.rectTransform.rect,point+new Vector2(0,.01f)),"ship crosses visible water before exit "+time);}if(time==22||time==26.4f||time==30.8f||time==34||time==44.01f)yield return Capture(width+"-ship-"+time.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture));}
            var end=CouncilChamber.ShipPoint(1);Check(end.x-.067f*.57f*.5f>.973f,"entire ship exits behind right jamb before quiet interval");Destroy(mesh);
        }
        Check(state==JsonUtility.ToJson(VariableSingleton.Instance.CaptureState())&&rng==JsonUtility.ToJson(UnityEngine.Random.state),"presentation preserves campaign and random stream");
    }
    IEnumerator Capture(string name){yield return null;Canvas.ForceUpdateCanvases();var go=new GameObject("Capture camera",typeof(Camera));var camera=go.GetComponent<Camera>();camera.orthographic=true;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;camera.nearClipPlane=.1f;camera.farClipPlane=100;var canvases=FindObjectsOfType<Canvas>().Where(c=>c.isRootCanvas).ToArray();var modes=canvases.Select(c=>c.renderMode).ToArray();var cams=canvases.Select(c=>c.worldCamera).ToArray();var distances=canvases.Select(c=>c.planeDistance).ToArray();var target=RenderTexture.GetTemporary(Screen.width,Screen.height,24);var prior=RenderTexture.active;Texture2D shot=null;try{camera.targetTexture=target;foreach(var c in canvases){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=camera;c.planeDistance=10;}Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=target;shot=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);shot.ReadPixels(new Rect(0,0,target.width,target.height),0,0);shot.Apply();File.WriteAllBytes(Path.Combine(output,name+".png"),shot.EncodeToPNG());}finally{RenderTexture.active=prior;for(int i=0;i<canvases.Length;i++){canvases[i].renderMode=modes[i];canvases[i].worldCamera=cams[i];canvases[i].planeDistance=distances[i];}camera.targetTexture=null;RenderTexture.ReleaseTemporary(target);if(shot!=null)Destroy(shot);Destroy(go);}}
}
#endif
